// Parse Qwen Score: strict parse only. No fence-stripping, no repair.
// Any failure throws so the run visibly fails instead of silently
// producing a "valid: false" success further down the chain.
const body = $json;
const choice = (body.choices && body.choices[0]) || {};
const message = choice.message || {};
const content = message.content;

if (typeof content !== 'string') {
  throw new Error('LOOM_SCORE_PARSE_FAILED: message.content is not a string (got ' + typeof content + ')');
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error('LOOM_SCORE_PARSE_FAILED: JSON.parse failed: ' + e.message);
}

return [{ json: { parsed } }];

// Validate LOOM Score: full contract check against the locked scoring
// contract (loom_candidate_semantic_score, v1.0). Any violation throws
// LOOM_SCORE_VALIDATION_FAILED so a bad model response fails the run
// loudly instead of returning valid:false as a "successful" output.
//
// NOTE: the hook word-count bound, caption char-count bound, and the
// overall_score weighting formula below are NOT part of Codex's locked
// JSON schema (that schema has no length/word constraints on these two
// text fields, and specifies no scoring formula at all). They are
// LOOM-side editorial/business rules layered on top, confirmed by Bryan.
// Reference "Build OpenRouter Request" instead of a single named entry-path
// node: BOTH entry paths (Manual Trigger -> Dummy Candidate Clip Data, and
// Execute Sub-workflow Trigger -> Validate Incoming Candidate) converge into
// this node before the OpenRouter call, and it spreads ...$json from
// whichever upstream node actually ran, so run_id/tenant_id/clip_id are
// always present here regardless of entry path. Referencing either entry
// node by name directly breaks on the OTHER path, since only one of them
// executes per run (observed: execution 9509/9512, "node X hasn't been
// executed").
const expected = $('Build OpenRouter Request').item.json;
const p = $json.parsed || {};
const errors = [];

const requiredFields = [
  'schema_version','run_id','tenant_id','clip_id',
  'hook_score','completeness_score','clarity_score','emotional_intensity_score',
  'shareability_score','context_dependency_score','duration_score','duration_fit',
  'dead_air_detected','repair_actions','hard_failure_codes','suggested_hook',
  'suggested_caption','confidence','evidence_summary','unverified_dimensions',
  'recommended_decision'
];
for (const f of requiredFields) {
  if (!(f in p)) errors.push(`missing required field: ${f}`);
}

// --- Identifier cross-check: must match what we actually sent, not just be present ---
if (p.run_id !== expected.run_id) errors.push(`run_id mismatch: expected ${expected.run_id}, got ${JSON.stringify(p.run_id)}`);
if (p.tenant_id !== expected.tenant_id) errors.push(`tenant_id mismatch: expected ${expected.tenant_id}, got ${JSON.stringify(p.tenant_id)}`);
if (p.clip_id !== expected.clip_id) errors.push(`clip_id mismatch: expected ${expected.clip_id}, got ${JSON.stringify(p.clip_id)}`);
if (p.schema_version !== '1.0') errors.push(`schema_version must be "1.0", got ${JSON.stringify(p.schema_version)}`);

// --- Score fields: integer 0-100 ---
const scoreFields = ['hook_score','completeness_score','clarity_score','emotional_intensity_score','shareability_score','context_dependency_score','duration_score'];
for (const f of scoreFields) {
  const v = p[f];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < 0 || v > 100) {
    errors.push(`${f} must be an integer 0-100, got: ${JSON.stringify(v)}`);
  }
}

// --- Enums ---
if (!['too_short','good','too_long'].includes(p.duration_fit)) {
  errors.push(`duration_fit invalid enum value: ${JSON.stringify(p.duration_fit)}`);
}
if (!['publishable','repairable','reject'].includes(p.recommended_decision)) {
  errors.push(`recommended_decision invalid enum value: ${JSON.stringify(p.recommended_decision)}`);
}

// --- confidence range ---
if (typeof p.confidence !== 'number' || p.confidence < 0 || p.confidence > 1) {
  errors.push(`confidence must be a number 0-1, got: ${JSON.stringify(p.confidence)}`);
}

// --- Array shape checks ---
const arrayFields = ['repair_actions','hard_failure_codes','unverified_dimensions'];
for (const f of arrayFields) {
  if (!Array.isArray(p[f])) errors.push(`${f} must be an array`);
}
if (!Array.isArray(p.evidence_summary) || p.evidence_summary.length < 1 || p.evidence_summary.length > 5) {
  errors.push('evidence_summary must be an array of 1-5 strings');
}

// --- Text field bounds (LOOM editorial rules, not from Codex's schema) ---
if (typeof p.suggested_hook !== 'string' || p.suggested_hook.trim().length === 0) {
  errors.push('suggested_hook must be a non-empty string');
} else {
  const wc = p.suggested_hook.trim().split(/\s+/).length;
  if (wc < 3 || wc > 10) {
    errors.push(`suggested_hook must be 3-10 words (3-7 preferred), got ${wc}: "${p.suggested_hook}"`);
  }
}
if (typeof p.suggested_caption !== 'string' || p.suggested_caption.trim().length === 0) {
  errors.push('suggested_caption must be a non-empty string');
} else if (p.suggested_caption.length > 220) {
  errors.push(`suggested_caption exceeds 220 characters (${p.suggested_caption.length})`);
}

// --- dead_air_detected null-consistency ---
// This pipeline is transcript-only (no audio/video access), so the model has
// no basis to judge dead air. Require null here; a true/false value means the
// model guessed at something it cannot actually observe from text alone.
if (p.dead_air_detected !== null) {
  errors.push(`dead_air_detected must be null for a transcript-only pipeline, got: ${JSON.stringify(p.dead_air_detected)}`);
}

// --- unverified_dimensions: pipeline-authoritative, not Qwen-authoritative ---
// Revised 2026-09-06: which dimensions are unverifiable for a transcript-only
// pipeline is STATIC KNOWLEDGE about what this pipeline can and cannot see --
// it does not depend on Qwen reliably enumerating all 7 every single call.
// Requiring Qwen's own list to be complete caused real validation failures
// when the model returned a partial (e.g. 6 of 7) but otherwise-correct list.
//
// New approach: n8n computes the authoritative list itself
// (requiredUnverifiedDimensions, hardcoded). Qwen's returned list is kept for
// observability only (modelUnverifiedDimensions) and is still checked for
// well-formedness -- it must be an array, and every value in it must be one
// of the 7 valid enum values (no fabricated dimension names) -- but it is no
// longer required to be complete, and it no longer decides the final output.
const requiredUnverifiedDimensions = ['crop_quality','speaker_visibility','facial_framing','subtitle_placement','audio_sync','camera_switching','dead_air'];
const modelUnverifiedDimensions = p.unverified_dimensions;

if (!Array.isArray(modelUnverifiedDimensions)) {
  errors.push('unverified_dimensions must be an array');
} else {
  const invalid = modelUnverifiedDimensions.filter(d => !requiredUnverifiedDimensions.includes(d));
  if (invalid.length > 0) {
    errors.push(`unverified_dimensions contains invalid/fabricated values not in the known enum: ${invalid.join(', ')}`);
  }
}

if (errors.length > 0) {
  throw new Error('LOOM_SCORE_VALIDATION_FAILED: ' + errors.join(' | '));
}

// --- Deterministic LOOM scoring (independent of the model's own recommendation) ---
// LOOM-side scoring formula, revised by Bryan on 2026-09-06 -- supersedes the
// earlier 30/15/15/15/15/5/5 weighting. Not derived from Codex's schema, which
// specifies no formula or weights of any kind for overall_score (overall_score
// itself is not a schema field -- it's a LOOM-computed metric layered on top).
// context_dependency_score is inverted here: a clip that depends heavily on
// external context to make sense is worse for short-form, so a HIGH
// context_dependency_score should PULL DOWN overall_score, not up.
const overall_score = Math.round(
  p.hook_score * 0.20 +
  p.completeness_score * 0.20 +
  p.clarity_score * 0.15 +
  p.emotional_intensity_score * 0.15 +
  p.shareability_score * 0.15 +
  (100 - p.context_dependency_score) * 0.10 +
  p.duration_score * 0.05
);

// Decision policy revised by Bryan on 2026-09-06: publishable now requires a
// higher overall_score bar (80, up from 70) PLUS three additional gates that
// did not exist before -- this is a new, stricter policy layered on top of
// the existing overall_score metric, not a fix to a defect in prior code
// (there was no previous context_dependency/completeness/clarity gate to
// "restore"). repairable floor also raised from 40 to 60, which narrows what
// counts as repairable vs. reject.
let decision;
if (p.hard_failure_codes.length > 0) {
  decision = 'reject';
} else if (
  overall_score >= 80 &&
  p.context_dependency_score <= 45 &&
  p.completeness_score >= 75 &&
  p.clarity_score >= 70 &&
  p.repair_actions.length === 0
) {
  decision = 'publishable';
} else if (overall_score >= 60) {
  decision = 'repairable';
} else {
  decision = 'reject';
}

const decision_agreement = decision === p.recommended_decision;

return [{ json: {
  parsed: p,
  overall_score,
  decision,
  model_recommended_decision: p.recommended_decision,
  decision_agreement,
  // Authoritative for downstream use -- pipeline-computed, not Qwen's raw list.
  // Qwen's own list is preserved separately purely for observability.
  authoritative_unverified_dimensions: requiredUnverifiedDimensions,
  model_unverified_dimensions: modelUnverifiedDimensions,
  openshorts_score: expected.predicted_score_openshorts
} }];

// Build OpenRouter Request: constructs the full request body as a real JS
// object (not a stringified {{ }} expression). Moved here specifically to
// avoid n8n's expression-delimiter parser mis-detecting the closing "}}" of
// the {{ }} wrapper when it collides with nested "}}" sequences inside a large
// inline JSON schema literal -- observed as "invalid syntax" on the HTTP node
// when the schema was embedded directly in its jsonBody expression.
const schema = {"name": "loom_candidate_semantic_score", "strict": true, "schema": {"type": "object", "additionalProperties": false, "properties": {"schema_version": {"type": "string", "enum": ["1.0"]}, "run_id": {"type": "string"}, "tenant_id": {"type": "string"}, "clip_id": {"type": "string"}, "hook_score": {"type": "integer", "minimum": 0, "maximum": 100}, "completeness_score": {"type": "integer", "minimum": 0, "maximum": 100}, "clarity_score": {"type": "integer", "minimum": 0, "maximum": 100}, "emotional_intensity_score": {"type": "integer", "minimum": 0, "maximum": 100}, "shareability_score": {"type": "integer", "minimum": 0, "maximum": 100}, "context_dependency_score": {"type": "integer", "minimum": 0, "maximum": 100}, "duration_score": {"type": "integer", "minimum": 0, "maximum": 100}, "duration_fit": {"type": "string", "enum": ["too_short", "good", "too_long"]}, "dead_air_detected": {"type": ["boolean", "null"]}, "repair_actions": {"type": "array", "uniqueItems": true, "items": {"type": "string", "enum": ["rewrite_hook", "rewrite_caption", "adjust_duration", "remove_dead_air", "needs_visual_verification", "needs_audio_verification"]}}, "hard_failure_codes": {"type": "array", "uniqueItems": true, "items": {"type": "string", "enum": ["incomplete_thought", "misleading_hook", "unintelligible_transcript", "missing_essential_context", "rights_or_policy_risk"]}}, "suggested_hook": {"type": "string"}, "suggested_caption": {"type": "string"}, "confidence": {"type": "number", "minimum": 0, "maximum": 1}, "evidence_summary": {"type": "array", "minItems": 1, "maxItems": 5, "items": {"type": "string"}}, "unverified_dimensions": {"type": "array", "uniqueItems": true, "items": {"type": "string", "enum": ["crop_quality", "speaker_visibility", "facial_framing", "subtitle_placement", "audio_sync", "camera_switching", "dead_air"]}}, "recommended_decision": {"type": "string", "enum": ["publishable", "repairable", "reject"]}}, "required": ["schema_version", "run_id", "tenant_id", "clip_id", "hook_score", "completeness_score", "clarity_score", "emotional_intensity_score", "shareability_score", "context_dependency_score", "duration_score", "duration_fit", "dead_air_detected", "repair_actions", "hard_failure_codes", "suggested_hook", "suggested_caption", "confidence", "evidence_summary", "unverified_dimensions", "recommended_decision"]}};

const requestBody = {
  model: "qwen/qwen3.5-9b",
  temperature: 0.2,
  max_tokens: 1200,
  reasoning: { effort: "none", exclude: true },
  response_format: {
    type: "json_schema",
    json_schema: schema
  },
  messages: [
    {
      role: "system",
      content: "You are a LOOM Factory clip-scoring assistant. Score the candidate short-form clip strictly according to the provided JSON schema. This pipeline only has the transcript (no video or audio access) -- mark ALL visual/audio dimensions (crop_quality, speaker_visibility, facial_framing, subtitle_placement, audio_sync, camera_switching, dead_air) in unverified_dimensions, and set dead_air_detected to null since you cannot judge it from text alone. Return only the fields defined in the schema, using the exact run_id, tenant_id, and clip_id provided. Each numeric score must be an integer from 0 to 100, where 0 is the weakest possible score and 100 is the strongest. Use the full 0–100 range. Do not use a 0–10 scale. suggested_hook must be 3-10 words (3-7 preferred)."
    },
    {
      role: "user",
      content: `Transcript: ${$json.no_speech ? '[NO SPEECH — instrumental clip; do not invent dialogue]' : $json.clip_transcript}\nHook text: ${$json.hook_text}\nDuration: ${$json.clip_duration_seconds}s\nrun_id: ${$json.run_id}\ntenant_id: ${$json.tenant_id}\nclip_id: ${$json.clip_id}`
    }
  ]
};

return [{ json: { ...$json, request_body: requestBody } }];

const input = $json;

const reservedKeys = [
  'model', 'temperature', 'max_tokens', 'reasoning', 'response_format',
  'json_schema', 'schema', 'weights', 'overall_score_weights',
  'decision_thresholds', 'prompt', 'system_prompt', 'credentials',
  'credential_id', 'openrouter_key', 'api_key'
];
const foundReserved = reservedKeys.filter(k => k in input);
if (foundReserved.length > 0) {
  throw new Error('LOOM_CANDIDATE_REJECTED: attempted override of locked scoring configuration: ' + foundReserved.join(', '));
}

const requiredFields = ['run_id', 'tenant_id', 'clip_id', 'source_id', 'candidate_clip_url', 'clip_duration_seconds', 'schema_version'];
if (input.no_speech !== true) {
  requiredFields.push('clip_transcript');
}
const missingRequired = requiredFields.filter(f => input[f] === undefined || input[f] === null || input[f] === '');
if (missingRequired.length > 0) {
  throw new Error('LOOM_CANDIDATE_REJECTED: missing required candidate field(s): ' + missingRequired.join(', '));
}

return [{ json: {
  ...input,
  clip_transcript: input.clip_transcript,
  hook_text: input.existing_hook || (input.no_speech === true ? '[no speech]' : '(no existing hook provided)'),
  predicted_score_openshorts: (input.openshorts_score === undefined ? null : input.openshorts_score),
  clip_duration_seconds: input.clip_duration_seconds,
  run_id: input.run_id,
  tenant_id: input.tenant_id,
  clip_id: input.clip_id
} }];
